def faction_of(col, lon, lat):
    f = FMAP.get(tuple(col))
    if f is None: return None
    if tuple(col) == (54, 167, 156) and lat > 42: f = 'trebizond'   # тот же бирюзовый в Крыму — Трапезунд (Перати́я)
    return f
